import openpyxl
from openpyxl.styles import PatternFill

wb = openpyxl.load_workbook('gdp.xlsx')
ws = wb['Task']

for r in [9, 10]:
    for c in range(1, 15):
        cell = ws.cell(row=r, column=c)
        if cell.fill and cell.fill.start_color.index != '00000000':
            print(f"Cell({r}, {c}) value={cell.value} color={cell.fill.start_color.index}")

print("\nChecking Column D for blue color")
for r in range(1, 40):
    cell = ws.cell(row=r, column=4)
    if cell.fill and cell.fill.start_color.index != '00000000':
        print(f"Cell({r}, 4) value={cell.value} color={cell.fill.start_color.index}")

